<?php
require_once __DIR__ . '/../includes/bootstrap.php'; $user=require_login('seeker'); $pdo=database();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $action=posted('action');
    if ($action==='profile') {$pdo->prepare('UPDATE job_seekers SET full_name=?,phone=?,address=?,date_of_birth=?,profile_summary=? WHERE user_id=?')->execute([posted('full_name'),posted('phone')?:null,posted('address')?:null,posted('date_of_birth')?:null,posted('profile_summary')?:null,$user['id']]); flash('success','Profile updated.');}
    if ($action==='skill' && posted('skill_name')!=='') {$pdo->prepare('INSERT INTO job_seeker_skills(seeker_id,skill_name,skill_level) VALUES(?,?,?) ON DUPLICATE KEY UPDATE skill_level=VALUES(skill_level)')->execute([$user['id'],posted('skill_name'),posted('skill_level')]); flash('success','Skill saved.');}
    if ($action==='education' && posted('institution')!=='' && posted('degree')!=='') {$pdo->prepare('INSERT INTO education(seeker_id,institution,degree,field_of_study,start_date,end_date,result_gpa) VALUES(?,?,?,?,?,?,?)')->execute([$user['id'],posted('institution'),posted('degree'),posted('field')?:null,posted('start_date')?:null,posted('end_date')?:null,posted('result')?:null]); flash('success','Education added.');}
    if ($action==='experience' && posted('company')!=='' && posted('position')!=='') {$pdo->prepare('INSERT INTO experience(seeker_id,company,position_title,description,start_date,end_date) VALUES(?,?,?,?,?,?)')->execute([$user['id'],posted('company'),posted('position'),posted('description')?:null,posted('start_date'),posted('end_date')?:null]); flash('success','Experience added.');}
    if ($action==='project' && posted('title')!=='') {$pdo->prepare('INSERT INTO projects(seeker_id,title,description,technologies,project_url) VALUES(?,?,?,?,?)')->execute([$user['id'],posted('title'),posted('description')?:null,posted('technologies')?:null,posted('url')?:null]); flash('success','Project added.');}
    if ($action==='certification' && posted('certification_name')!=='') {$pdo->prepare('INSERT INTO certifications(seeker_id,certification_name,issuing_organization,issue_date,credential_url) VALUES(?,?,?,?,?)')->execute([$user['id'],posted('certification_name'),posted('issuer'),posted('issue_date')?:null,posted('url')?:null]); flash('success','Certification added.');}
    if ($action==='language' && posted('language_name')!=='') {$pdo->prepare('INSERT INTO languages(seeker_id,language_name,proficiency) VALUES(?,?,?) ON DUPLICATE KEY UPDATE proficiency=VALUES(proficiency)')->execute([$user['id'],posted('language_name'),posted('proficiency')]); flash('success','Language saved.');} redirect('profile.php'); }
$s=$pdo->prepare('SELECT js.*,u.email FROM job_seekers js JOIN users u ON u.id=js.user_id WHERE js.user_id=?');$s->execute([$user['id']]);$profile=$s->fetch(); page_header('My profile'); ?>
