ation</h2><label>Name</label><input name="certification_name" required><label>Issuer</label><input name="issuer" required><label>Issue date</label><input type="date" name="issue_date"><label>Credential URL</label><input name="url" type="url"><p><button>Add certification</button></p></form><form method="post"><input type="hidden" name="csrf_token" value="<?=csrf_token() ?>"><input type="hidden" name="action" value="language"><h2>Language</h2><label>Language</label><input name="language_name" required><label>Proficiency</label><select name="proficiency"><option>basic</option><option>conversational</option><option>professional</option><option>native</option></select><p><button>Add language</button></p></form></section>
